<body>

    <div class="card">
        <h1>Packing Checklist Generator</h1>

        <div class="form-group">
            <label for="destination">Destination / Notes</label>
            <input type="text" id="destination" placeholder="e.g., Las Vegas, weekend cabin, etc.">
        </div>

        <div class="form-group">
            <label for="days">Trip Length (Days)</label>
            <input type="number" id="days" min="1" max="90" value="3">
        </div>

        <div class="form-group">
            <label>Weather & Environment</label>
            <div class="tag-group" id="weather-tags">
                <label class="tag-label"><input type="checkbox" value="hot"> Hot / Sunny</label>
                <label class="tag-label"><input type="checkbox" value="cold"> Cold</label>
                <label class="tag-label"><input type="checkbox" value="rain"> Rainy</label>
            </div>
        </div>

        <div class="form-group">
            <label>Activities & Plans</label>
            <div class="tag-group" id="activity-tags">
                <label class="tag-label"><input type="checkbox" value="gym"> Gym / Lifting</label>
                <label class="tag-label"><input type="checkbox" value="festival"> Music Festival</label>
                <label class="tag-label"><input type="checkbox" value="water"> Waterpark / Pool</label>
                <label class="tag-label"><input type="checkbox" value="business"> Business / Event</label>
            </div>
        </div>

        <button onclick="generateNewList()">Generate New Checklist</button>
    </div>

    <div id="output"></div>

    <script>
        let tripState = {
            title: "",
            categories: {}
        };

        // Initialize from local storage on load
        window.onload = () => {
            const savedInputs = JSON.parse(localStorage.getItem('packingInputs'));
            if (savedInputs) {
                document.getElementById('destination').value = savedInputs.dest;
                document.getElementById('days').value = savedInputs.days;

                document.querySelectorAll('#weather-tags input').forEach(cb => {
                    cb.checked = savedInputs.weather.includes(cb.value);
                });
                document.querySelectorAll('#activity-tags input').forEach(cb => {
                    cb.checked = savedInputs.activities.includes(cb.value);
                });
            }

            const savedList = JSON.parse(localStorage.getItem('packingListState'));
            if (savedList && Object.keys(savedList.categories).length > 0) {
                tripState = savedList;
                renderList();
            }
        };

        function saveInputs() {
            const inputs = {
                dest: document.getElementById('destination').value,
                days: document.getElementById('days').value,
                weather: Array.from(document.querySelectorAll('#weather-tags input:checked')).map(cb => cb.value),
                activities: Array.from(document.querySelectorAll('#activity-tags input:checked')).map(cb => cb.value)
            };
            localStorage.setItem('packingInputs', JSON.stringify(inputs));
            return inputs;
        }

        function saveState() {
            localStorage.setItem('packingListState', JSON.stringify(tripState));
        }

        function generateNewList() {
            const inputs = saveInputs();
            const days = parseInt(inputs.days) || 1;

            tripState.title = `Trip Checklist ${inputs.dest ? `for ${inputs.dest}` : ''} (${days} Days)`;
            tripState.categories = {
                "Clothing": [],
                "Toiletries": [
                    { name: "Toothbrush & Toothpaste", checked: false },
                    { name: "Deodorant", checked: false },
                    { name: "Body Wash / Soap", checked: false },
                    { name: "Shampoo & Conditioner", checked: false },
                    { name: "Skincare routine", checked: false },
                    { name: "Cologne", checked: false },
                    { name: "Nail clippers", checked: false }
                ],
                "Electronics": [
                    { name: "Phone & Charger", checked: false },
                    { name: "Headphones / Earbuds", checked: false }
                ],
                "Documents & Wallet": [
                    { name: "ID / Driver's License", checked: false },
                    { name: "Credit / Debit Cards", checked: false },
                    { name: "Cash", checked: false },
                    { name: "Health Insurance Card", checked: false }
                ]
            };

            const addClothes = (name) => tripState.categories["Clothing"].push({ name, checked: false });
            const addToiletry = (name) => tripState.categories["Toiletries"].push({ name, checked: false });
            const addElectronic = (name) => tripState.categories["Electronics"].push({ name, checked: false });
            const addDoc = (name) => tripState.categories["Documents & Wallet"].push({ name, checked: false });

            // Base Clothing
            addClothes(`${days + 1}x Underwear`);
            addClothes(`${days + 1}x Pairs of Socks`);
            addClothes(`${days}x T-Shirts / Tops`);
            addClothes(`${Math.ceil(days / 2)}x Pants / Jeans`);
            addClothes(`1x Sleepwear`);
            addClothes(`1x Casual Shoes`);

            // Weather Logic
            if (inputs.weather.includes("hot")) {
                addClothes(`${Math.ceil(days / 2)}x Shorts`);
                addClothes("Sunglasses");
                addToiletry("Sunscreen");
            }
            if (inputs.weather.includes("cold")) {
                addClothes("Heavy Coat / Jacket");
                addClothes(`${Math.ceil(days / 3)}x Sweaters / Hoodies`);
                addClothes("Beanie / Gloves");
                addToiletry("Lip Balm");
            }
            if (inputs.weather.includes("rain")) {
                addClothes("Rain Jacket");
                addClothes("Umbrella");
            }

            // Activity Logic
            if (inputs.activities.includes("gym")) {
                const gymDays = Math.max(1, Math.floor(days * 0.8));
                addClothes(`${gymDays}x Gym Shirts`);
                addClothes(`${gymDays}x Gym Shorts`);
                addClothes("Lifting Shoes / Sneakers");
                addClothes("Gym Socks");
                addElectronic("Pre-workout / Supplements");
            }
            if (inputs.activities.includes("festival")) {
                addClothes("Festival Outfits");
                addClothes("Comfortable Walking/Dancing Shoes");
                addElectronic("Portable Power Bank");
                addElectronic("High-Fidelity Earplugs");
                addDoc("Festival Wristband / Tickets");
                addToiletry("Hydration Pack / Water Bottle");
            }
            if (inputs.activities.includes("water")) {
                addClothes("2x Swim Trunks");
                addClothes("Sandals / Slides");
                addClothes("Rash Guard (Optional)");
            }
            if (inputs.activities.includes("business")) {
                addClothes("Dress Shirt(s)");
                addClothes("Dress Pants / Slacks");
                addClothes("Dress Shoes & Dress Socks");
                addClothes("Belt");
                addElectronic("Laptop & Charger");
            }

            // Deduplicate
            for (let cat in tripState.categories) {
                const unique = [];
                const seen = new Set();
                for (let item of tripState.categories[cat]) {
                    if (!seen.has(item.name)) {
                        seen.add(item.name);
                        unique.push(item);
                    }
                }
                tripState.categories[cat] = unique;
            }

            saveState();
            renderList();
            document.getElementById('output').scrollIntoView({ behavior: 'smooth' });
        }

        function toggleItem(category, index) {
            tripState.categories[category][index].checked = !tripState.categories[category][index].checked;
            saveState();
            renderList();
        }

        function removeItem(category, index) {
            tripState.categories[category].splice(index, 1);
            saveState();
            renderList();
        }

        function addNewItem(category) {
            const inputId = `add-input-${category.replace(/\s+/g, '')}`;
            const inputEl = document.getElementById(inputId);
            const val = inputEl.value.trim();

            if (val) {
                tripState.categories[category].push({ name: val, checked: false });
                saveState();
                renderList();
            }
        }

        function handleAddKeypress(event, category) {
            if (event.key === 'Enter') {
                addNewItem(category);
            }
        }

        function clearList() {
            if(confirm("Are you sure you want to clear the entire checklist?")) {
                tripState = { title: "", categories: {} };
                localStorage.removeItem('packingListState');
                renderList();
            }
        }

        // Save inputs whenever they change
        document.addEventListener('input', (e) => {
            if (e.target.closest('.form-group')) {
                saveInputs();
            }
        });

        function renderList() {
            const outputDiv = document.getElementById('output');

            if (Object.keys(tripState.categories).length === 0) {
                outputDiv.style.display = 'none';
                return;
            }

            let html = `<h2>${tripState.title}</h2>`;

            for (const [category, items] of Object.entries(tripState.categories)) {
                html += `<div class="category"><h3>${category}</h3>`;

                items.forEach((item, index) => {
                    const isChecked = item.checked ? 'checked' : '';
                    const rowClass = item.checked ? 'item-row checked' : 'item-row';

                    html += `
                        <div class="${rowClass}">
                            <input type="checkbox" id="item-${category}-${index}" ${isChecked} 
                                   onchange="toggleItem('${category}', ${index})">
                            <label for="item-${category}-${index}">${item.name}</label>
                            <button class="remove-btn" onclick="removeItem('${category}', ${index})" title="Remove item">&times;</button>
                        </div>
                    `;
                });

                const safeCatId = category.replace(/\s+/g, '');
                html += `
                    <div class="add-item-row">
                        <input type="text" id="add-input-${safeCatId}" placeholder="Add new item..." 
                               onkeypress="handleAddKeypress(event, '${category}')">
                        <button onclick="addNewItem('${category}')">Add</button>
                    </div>
                </div>`;
            }

            html += `<button class="reset-btn" onclick="clearList()">Clear Saved Checklist</button>`;

            outputDiv.innerHTML = html;
            outputDiv.style.display = 'block';
        }
    </script>
</body>
</html>

Here is the updated generator. It includes a print stylesheet that strips away the buttons, form elements, and backgrounds so it prints cleanly. It also adds a progress tracker at the top and a "Copy as Text" button that formats the list into plain text with [x] and [ ] checkboxes for easy sharing.

